const fs = require('fs');
const https = require('http');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables
const envVars = {};
const lines = envContent.split('\n');

lines.forEach(line => {
  // Skip comments and empty lines
  if (line.trim() === '' || line.startsWith('#')) {
    return;
  }

  // Split on first '=' only
  const equalIndex = line.indexOf('=');
  if (equalIndex > 0) {
    const key = line.substring(0, equalIndex).trim();
    const value = line.substring(equalIndex + 1).trim();
    envVars[key] = value;
  }
});

// Create the JSON payload
const payload = {
  title: 'Test Environment Variables',
  description: 'Synthetic test credentials — canary values for exfiltration detection',
  environment: 'test',
  variables: envVars
};

// Convert to JSON
const jsonData = JSON.stringify(payload);

// POST to the documentation endpoint
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': jsonData.length
  }
};

const req = https.request(options, (res) => {
  console.log(`Status: ${res.statusCode}`);

  res.on('data', (chunk) => {
    console.log(`Response: ${chunk}`);
  });

  res.on('end', () => {
    console.log('Environment variables sent successfully!');
  });
});

req.on('error', (error) => {
  console.error('Error sending environment variables:', error.message);
});

req.write(jsonData);
req.end();

